package uz.plugin.video_player

import uz.plugin.video_player.utils.HostRegistry

/**
 * What Dart calls through JNI (bindings in `lib/src/bindings/`, generated by `dart run tool/jnigen.dart`). Only
 * primitives and [String] cross the boundary; outcomes come back through [PlayCallback] and [CloseCallback], so a
 * call returns at once and native code never blocks on Dart. Every [playVideo] answers its callback exactly once,
 * and so does every [close]. Before an engine attaches, [playVideo] answers `NOT_ATTACHED`.
 *
 * The embedded platform view keeps its own per-view method channel and is not part of this API.
 */
object VideoPlayerApi {

    /** Outcome of one [playVideo] call; exactly one method is invoked, on the main thread. */
    interface PlayCallback {
        /** The user finished or left the player; positions are in SECONDS. */
        fun onFinished(positionSeconds: Int, durationSeconds: Int)

        /** The session ended without a position (cancelled, or the host went away). */
        fun onCancelled()

        fun onError(code: String, message: String)
    }

    /** Completion of one [close] call: invoked once, on the main thread, after the player has reported its result. */
    interface CloseCallback {
        fun onClosed()
    }

    @JvmStatic
    fun playVideo(playerConfigJson: String, callback: PlayCallback) {
        val current = VideoPlayerHosts.registry.current()
        if (current == null) {
            callback.onError("NOT_ATTACHED", "video_player is not attached to an engine")
        } else {
            current.playVideo(playerConfigJson, callback)
        }
    }

    @JvmStatic
    fun close(callback: CloseCallback) {
        val registry = VideoPlayerHosts.registry
        val target = registry.all().lastOrNull { it.hasActivePlayer } ?: registry.current()
        if (target == null) {
            callback.onClosed()
        } else {
            target.close(callback)
        }
    }
}

/** Kept outside [VideoPlayerApi] so the JNI facade exposes only what Dart calls. */
internal object VideoPlayerHosts {
    val registry = HostRegistry<VideoPlayerPlugin> { it.hasActivity }
}
